public struct ToolResult: Hashable, Codable, Sendable {
    public let content: [Tool.Content]?
    public let isError: Bool?

    public init(content: [Tool.Content]? = nil, isError: Bool? = nil) {
        self.content = content
        self.isError = isError
    }
}

